-- Private attachment metadata is never a public URL. No upload can mark ready until isolated validation is implemented.
CREATE TABLE private_attachment(id uuid PRIMARY KEY,employee_id uuid NOT NULL REFERENCES employee(id),purpose text NOT NULL CHECK(purpose IN ('receipt','medical')),state text NOT NULL CHECK(state IN ('quarantined','ready')),verified_mime text NOT NULL CHECK(verified_mime IN ('image/jpeg','image/png','image/heic','application/pdf')),size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 20971520),checksum text NOT NULL CHECK(checksum ~ '^[a-f0-9]{64}$'));
CREATE TABLE claim(id uuid PRIMARY KEY,employee_id uuid NOT NULL REFERENCES employee(id),description text NOT NULL,expense_date text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents BETWEEN 1 AND 9007199254740991),state text NOT NULL CHECK(state IN ('pending','approved','rejected','withdrawn','allocated')),revision integer NOT NULL DEFAULT 1,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claim_attachment(claim_id uuid NOT NULL REFERENCES claim(id),attachment_id uuid NOT NULL REFERENCES private_attachment(id),PRIMARY KEY(claim_id,attachment_id));
CREATE TABLE claim_mutation(actor_id text NOT NULL REFERENCES "user"(id),request_key text NOT NULL,fingerprint text NOT NULL,claim_id uuid NOT NULL REFERENCES claim(id),PRIMARY KEY(actor_id,request_key));
